INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66584659', 66584659, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RSU DR KARIADI SEMARANG', 'Pengadaan Tambahan Bahan Makanan Basah FnB Kelompok Telur dan Nabati serta Kelompok Daging Sapi Maret - Juni Tahun 2026', 'Barang', 'Pengadaan Langsung', 'Jawa Tengah, Semarang (Kota)', 74050000, 'March 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Pengadaan Tambahan Bahan Makanan Basah FnB Kelompok Telur dan Nabati serta Kelompok Daging Sapi Maret - Juni Tahun 2026', '//Kelompok Telur dan Nabati 1 Tahu goreng Warna coklat muda, tidak tengik, baru, tidak pahit, tanpa bahan campuran, tanpa pewarna, tanpa pengawet (bebas boraks/formalin), berat minimal 50 gr, dikemas dalam kontainer plastik tertutup. 2 Tahu Putih Tahu cetak atau pres, segar, padat, kenyal, aroma khas tahu, tak mudah hancur, tanpa bahan campuran, tanpa pewarna, tanpa pengawet (bebas boraks/formalin), tidak pahit, berat minimal 50 gr, sesudah ditiriskan selama 30 menit, dikemas dalam kontainer plastik tertutup. 3 Telor ayam Baru, bentuk bulat, mulus tidak bergelombang, tidak retak, kulit warna kecoklatan, bersih dari kotoran, berat antara 60-70 gr. Kemasan pengiriman dengan plang telur plastik dengan kondisi bersih. Jika setelah direbus ternyata tidak dapat digunakan karena antara lain : telur busuk, kuning telur lepas dari putihnya, setelah dikupas permukaan putih telur tidak mulus, maka telur yang rusak/tidak sesuai akan ditukar dengan telur mentah yang baru. 4 Telor puyuh Sudah matang, terkupas, tidak busuk, segar, warna putih, permukaan mulus, kuning telur tidak lepas dari putihnya, utuh, berat minimal 10 gr, Dikemas dalam kontainer plastik tertutup, dikirim dalam suhu dingin 5 - 10°C (kontainer dilengkapi ice pack/ice bag) 5 Tempe Bahan kedelai murni,tidak campuran, tidak semangit, tidak mudah hancur, bentuk kotak segi empat, berat minimal 50 gr, tebal maksimal 1,5 cm, dikemas dalam kontainer plastik tertutup. 6 Tofu Jenis tahu sutra (silkin tofu), terbuat dari kedelai, rasa telur, utuh, tidak retak, tidak hancur, kemasan plastik pabrikasi, bebas boraks dan formalin, netto antara 230-240 gram, ijin BPOM, tersertifikasi halal, tidak kadaluarsa minimal 1 bulan, jika dibelah hancur maka akan dikembalikan, merk Sakura. //Kelompok Daging Sapi 1 Bakso sapi Terbuat dari daging sapi, dikirim beku/frozen, tidak berbau amis, keset. Netto 250 gr per kemasan yang berisi ± 20 biji bakso. Dikemas dalam plastik pabrikasi, bebas boraks dan formalin, tidak ada tambahan pengawet, tersertifikasi halal, tidak kadaluarsa dalam waktu 3 bulan, dikirim dalam cool box dilengkapi ice gel/ice pack dengan suhu dingin (≤ 5 °C), merk Nandisari dengan kode C atau 03 2 Daging sapi Jenis hot meat/fresh meat, warna merah segar (tidak biru), baru, kenyal, bagian has luar, daging knuckle/daging gandik tidak berlendir, tidak beku, kesat/ tidak berair, tidak dari sapi gelonggong, tidak diawetkan dengan bahan pengawet (sendowo), bebas boraks dan formalin, tanpa pewarna, tidak ada benda asing, tanpa lapisan lemak dan otot, sapi muda. Daging sapi resmi berasal dari RPH yang bersertifikat nomor kontrol veteriner dan sertifikat halal. Dikirim dalam kontainer tertutup dengan alat transportasi dengan suhu dingin (5-10 °C) 3 Daging sapi sukiyaki Bentuk lembaran daging irisan tipis tanpa lemak, dikirim frozen/beku, warna merah, tebal irisan 1 mm, dalam kemasan tertutup, Produk daging sapi resmi berasal dari RPH yang bersertifikat halal, dikirim dalam cool box dilengkapi ice gel/ice pack dengan suhu dingin (≤ 5 °C). 4 Iga Sapi Bagian tulang sapi yang berasal dari tulang rusuk yang sudah terpotong dengan ukuran panjang ± 6 cm, lebar ± 5 cm, tebal ± 2 cm. Masih tebal dagingnya, berwarna merah segar, baru, kenyal, tidak berlendir, tidak beku, kesat/tidak berair, tidak dari sapi gelonggong, tidak diawetkan dengan bahan pengawet (sendowo), Produk daging sapi resmi berasal dari RPH yang bersertifikat halal, dikirim dalam cool box dilengkapi ice gel/ice pack dengan suhu dingin (5-10 °C). 5 Tulang sapi Sekengkel, baru, segar, tidak barbau busuk, bersumsum, dikemas dalam kontainer plastik tertutup, Produk daging sapi resmi berasal dari RPH yang bersertifikat halal, dikirim dalam cool box dilengkapi ice gel/ice pack dengan suhu dingin (5-10 °C).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2861172);
