INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66589388', 66589388, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN PAKET TENAGA ALIH DAYA PENGELOLA RKAKL DAN PENYUSUN LAPORAN KINERJA  ANGGARAN PPN VI SEKRETARIAT DEPUTI BIDANG PEMBANGUNAN MANUSIA DAN KEBUDAYAAN TAHUN ANGGARAN 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 118110375, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mendukung Perencanaan & Penganggaran Mengkoordinasikan penyusunan dan mereviu Kerangka Acuan Kerja (KAK), Rencana Anggaran Belanja (RAB), Rencana Penarikan Dana (RPD) dan Rencana Pelaksanaan Kegiatan (RPK) dari unit kerja. Menginput KAK dan RAB ke sistem SIRENA. Menyusun dan menginput RKAKL tahun berikutnya ke aplikasi SAKTI. Mengkonsolidasikan pagu rutin dan kebutuhan anggaran kegiatan tahunan. Mendukung Pengelolaan Anggaran & Monitoring Evaluasi Menganalisis data penyerapan anggaran dan realisasi keuangan setiap bulan. Melakukan analisis realisasi anggaran menggunakan data dari SIMBAR. Menyiapkan dan mengkoordinasikan revisi DIPA tahun berjalan. Menyusun dan menginput revisi RKAKL tahun berjalan ke aplikasi SAKTI Menginput target dan realisasi capaian output ke aplikasi SAKTI setiap bulan. Menginput data monitoring dan evaluasi kegiatan ke e-Performance. Melakukan rekonsiliasi pagu secara rutin bersama dengan biro renortala dan/atau biro umum Mengkoordinasikan pelaporan penyerapan dan kinerja dengan admin keuangan atau koordinator kegiatan/PPK. Mendukung Pengadaan Barang/Jasa Mereviu draf KAK dan draft SPK yang disusun oleh Person in Charge (PIC). Melakukan reviu dokumen pengadaan berdasarkan KAK, RAB, dan kebutuhan unit kerja. Menyiapkan template dokumen perjanjian/kontrak/Surat Perjanjian Kerja Sama (SPK). Mendukung Administrasi dan Konsolidasi Informasi Menyiapkan materi rapat rutin anggaran dan administrasi. Menyusun dan menyiapkan dokumen pendukung seperti nota dinas, undangan rapat, dan bahan paparan terkait keuangan dan pengadaan. Melakukan konsolidasi informasi terkait proses persetujuan dokumen dengan biro terkait. Berkomunikasi dan berkoordinasi aktif dengan PIC di masing-masing biro atau direktorat. Melaksanakan tugas lain sesuai penugasan pimpinan atau kebutuhan organisasi yang berkaitan dengan penguatan manajemen internal, perencanaan, atau pengelolaan anggaran.', 'Berpendidikan minimal S1 (Sarjana) atau S2 (Master) di bidang Matematika/Finansial/Manajemen Keuangan dari Perguruan Tinggi akreditasi A (diutamakan S2); Usia minimal 30 (tiga puluh) tahun; Memiliki pengalaman kerja minimal 9 (sembilan) tahun di bidang manajemen keuangan atau terkait; Terampil dan cermat dalam memahami isu, menganalisis data, serta dapat merumuskan dalam bahan presentasi; Berpengalaman dalam pengelolaan data kuantitatif; Pengalaman bekerja di lingkungan atau instansi pemerintahan (menjadi nilai tambah); Memahami aplikasi SAKTI, SIRENA, SIMBAR, e-Performance (menjadi nilai tambah); Menguasai penyusunan dokumen pengadaan, RAB, KAK dan administrasi keuangan; Memiliki kemampuan komunikasi, analisis data, dan koordinasi lintas unit; Teliti, mampu bekerja dengan target waktu, dan menjaga kerahasiaan dokumen. Memiliki inisiatif untuk mempelajari isu-isu terkini, mengidentifikasi kebutuhan pengumpulan data, serta berkoordinasi dengan berbagai pihak terkait untuk mempercepat pencapaian output; Berkepribadian baik, mampu bekerja sama, dan memiliki inisiatif dalam bekerja; Tidak berstatus sebagai ASN (PNS/TNI/Polri).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2863622);
