INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66589557', 66589557, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Pemantauan Pembangunan Perkotaan Berkelanjutan Berbasis Spasial  Kegiatan Koordinasi Strategis Pembangunan Perkotaan Nasional Direktorat Tata Ruang, Perkotaan, Pertanahan, dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 147420000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Memberikan dukungan keahlian untuk penyusunan instrumen pemantauan proyek prioritas berbasis spasial pada lokasi prioritas perkotaan dalam RPJMN 2025-2029; 2. Membantu melakukan inventarisasi, koleksi dan sistematisasi basis data perkotaan nasional berbasis spasial, utamanya untuk lokasi prioritas pembangunan perkotaan dalam RPJMN 2025-2029; 3. Memberikan dukungan keahlian dalam pemantauan proyek prioritas berbasi spasial pada Program Prioritas Pembangunan Perkotaan Berkelanjutan, utamanya untuk 10 Wilayah Metropolitan, 4 Calon Wilayah Metropolitan, dan 36 (tiga puluh enam) perkotaan non-wilayah metropolitan lainnya yang terbagi ke dalam perkotaan besar, perkotaan sedang dan perkotaan kecil; 4. Membantu menyusun dashboard kegiatan/proyek prioritas dan database pemantauan berbasis spasial untuk wilayah metropolitan dan perkotaan non-wilayah metropolitan', '1. Merupakan Jasa Konsultan Individu dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki Pendidikan minimal S1 Perencanaan Wilayah dan Kota/Geografi/Ekonomi/Studi Pembangunan (dibuktikan dengan ijazah); 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; 5. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristk lainnya yang bisa menggambarkan kesamaan) minimal 7 (tujuh) tahun di bidang perencanaan pembangunan perkotaan, termasuk di dalamnya pemantauan perkotaan dan analisis data spasial (dibuktikan dengan surat keterangan kerja/surat referensi kerja/bukti kontrak);', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2864042);
