INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66593245', 66593245, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN TENAGA ALIH DAYA PENYUSUNAN LAPORAN KEGIATAN KOORDINASI STRATEGIS PENGELOLAAN PROGRAM KERJASAMA RI-UNICEF TAHUN 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 95992533, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mendukung pelaksanaan program kerjasama Pemerintah RI-UNICEF khususnya dalam lingkup Bappenas dalam rangka kelancaran pelaksanaan Kegiatan Koordinasi Strategi Pengelolaan Program Kerja sama Rl-UNICEF Tahun 2026.', '1. Tidak berstatus sebagai ASN atau anggota TNI/Polri; 2. Pendidikan minimal S1 (Sarjana) bidang Kesehatan/Gizi/Manajemen/kesehatan masyarakat/ kebijakan publik/ ekonomi pembangunan/ ekonomi bisnis yang dibuktikan dengan ijazah; 3. Memiliki pengalaman minimal 2 tahun dalam koordinasi program kerjasama internasional dibuktikan dengan Surat Pengalaman kerja; 4. Memiliki kemampuan yang baik dalam manajemen data/ informasi, mengolah, menyajikan dan menganalisis data/informasi dan menulis laporan; 5. Memiliki kemampuan dalam koordinasi lintas kementerian lembaga; 6. Bersedia bekerja full time dan standby setiap saat dibutuhkan; 7. Bersedia untuk melakukan perjalanan dinas ke daerah dalam rangka pengumpulan data, apabila dibutuhkan; dan 8. Mampu bekerja dengan baik, disiplin dan sungguh-sungguh serta mempunyai komitmen dan motivasi untuk bekerja sama dalam tim.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2864900);
