INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66594316', 66594316, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'TENAGA PENDUKUNG PENYUSUNAN LAPORAN HASIL PENDATAAN PEMBANGUNAN BIDANG PENDIDIKAN', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 102414420, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Memberikan dukungan teknis dan administratif kepada Direktorat Pendidikan Dasar dan Menengah Kementerian PPN/Bappenas dalam pengelolaan, pemutakhiran, dan penyajian data serta informasi pembangunan bidang pendidikan, guna mendukung proses perencanaan, koordinasi, monitoring, dan evaluasi program dan kegiatan sesuai arah kebijakan yang telah ditetapkan.', 'a) Tidak berstatus sebagai ASN (PNS/TNI/Polri/); b) Pendidikan minimal S1 jurusan Statistika dari Perguruan Tinggi dalam atau luar negeri dengan akreditasi A; c) IPK minimal 3,50 (dari skala 4,00); d) Memiliki pengalaman kerja diatas 3 (tiga) tahun dalam dukungan pengelolaan data, penyusunan bahan pendukung, atau kegiatan teknis administratif pada bidang pembangunan pendidikan; e) Memiliki kemampuan dan pengalaman dalam pengumpulan, pengolahan, analisis data serta menulis laporan; f) Mampu mengoperasikan software pengolahan data statistik (SPSS/Stata/lainnya) menjadi nilai tambah; g) Mampu bekerja dengan baik, disiplin, dan sungguh-sungguh serta mempunyai komitmen dan motivasi untuk bekerjasama dalam tim; h) Memiliki inisiatif untuk mempelajari isu-isu terkini, melaksanakan pengumpulan data sesuai kebutuhan dan arahan unit kerja serta berkoordinasi dengan pihak terkait untuk mempercepat pencapaian output; i) Berkomitmen untuk mulai bekerja bulan Februari - Desember 2026 dan memberikan output terbaik sesuai dengan batas waktu yang ditetapkan; dan j) Mempunyai NPWP.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2866419);
