INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66594810', 66594810, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Model Transformasi Pembangunan Dan Ketimpangan Regional', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 195000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan ini bertujuan menghasilkan kajian strategis mengenai ketimpangan wilayah, pusat pertumbuhan, kerentanan sosial-ekonomi, serta konektivitas dan kelembagaan pemerataan sebagai dasar rekomendasi kebijakan dan strategi percepatan pemerataan pembangunan yang berbasis data, inklusif, dan berkelanjutan.', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Model Transformasi Pembangunan Dan Ketimpangan Regional diarahkan untuk menghasilkan kerangka analisis dan kajian strategis yang mampu menjelaskan mengapa ketimpangan dan ketidakterpaduan pembangunan wilayah terjadi, bagaimana dinamika tersebut berkembang lintas waktu dan wilayah, serta apa implikasinya bagi perumusan strategi pemerataan pembangunan nasional. Lingkup pekerjaan mencakup: Pengembangan kerangka analisis struktur ekonomi dan tipologi wilayah, yang tidak hanya memetakan perbedaan karakteristik wilayah, tetapi juga mengklasifikasikan posisi setiap wilayah dalam spektrum pembangunan (maju, berkembang, tertekan, tertinggal) berdasarkan kapasitas pertumbuhan, basis sektoral, dan ketergantungan ekonomi, sebagai dasar penentuan fokus dan diferensiasi strategi pemerataan. Pendalaman analisis dinamika ketimpangan dan pergeseran pusat-pusat pertumbuhan, untuk mengidentifikasi pola konvergensi dan divergensi pembangunan antarwilayah serta memahami mekanisme perubahan gravitasi ekonomi, sehingga dapat dibedakan antara wilayah yang mengalami akselerasi struktural dan wilayah yang mengalami stagnasi atau eksklusi pembangunan. Perumusan kajian strategis ketimpangan sosial-ekonomi dan kerentanan wilayah, yang mengaitkan kondisi kemiskinan, ketenagakerjaan, daya beli, dan kualitas sumber daya manusia dengan dinamika ekonomi wilayah, guna mengidentifikasi wilayah berisiko tinggi tertinggal dan menyusun dasar analitis bagi penajaman intervensi afirmatif yang lebih tepat sasaran. Penyusunan kerangka analisis integrasi wilayah dan kesiapan kelembagaan, yang menilai sejauh mana konektivitas fisik dan ekonomi, keterkaitan pasar, serta kapasitas koordinasi pusat–daerah memengaruhi aliran manfaat pembangunan antarwilayah, sekaligus mengidentifikasi hambatan struktural yang menghambat proses integrasi pembangunan regional. Sintesis hasil analisis ke dalam bahan kajian strategis dan narasi kebijakan, yang mengintegrasikan temuan lintas dimensi menjadi pemahaman utuh mengenai dinamika pembangunan dan integrasi wilayah, sebagai masukan teknis bagi penyiapan rekomendasi kebijakan pemerataan pembangunan wilayah, tanpa mencakup kewenangan penetapan atau pengambilan keputusan kebijakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2868131);
