INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66597979', 66597979, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN TENAGA ALIH DAYA PENYUSUNAN LAPORAN HASIL DATA EVALUASI TERPADU PEMBANGUNAN NASIONAL LINGKUP AGAMA, KEBUDAYAAN, PEMUDA, DAN OLAHRAGA', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 110308896, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Membantu Direktorat AKPO Kementerian PPN/Bappenas dalam pelaksanaan evaluasi terpadu pembangunan nasional lingkup agama, kebudayaan, pemuda, dan olahraga dan menyusun laporan informasi hasil pelaksanaan rencana pembangunan lingkup AKPO.', '1. Pendidikan minimal S1 dalam jurusan ilmu politik dengan akreditasi A; 2. IPK minimal 3,50 (dari skala 4,00); 3. Memiliki pengalaman kerja minimal 2 (dua) tahun di bidang pembangunan pemuda; 4. Memiliki pengalaman dalam penyusunan dokumen perencanaan pembangunan seperti RPJPN, RPJMN, dan RKP khususnya lingkup Agama, Kebudayaan, Pemuda, dan Olahraga. 5. Memiliki kemampuan dalam pengumpulan, pengolahan, analisis data serta menulis laporan; 6. Menguasai Microsoft Word, Excel, dan Power Point; 7. Pengalaman bekerja di lingkungan atau instansi pemerintahan menjadi nilai tambah; 8. Memiliki kemampuan bahasa Inggris yang baik (aktif); 9. Memiliki inisiatif, cekatan, kemauan belajar, komunikatif, dan dapat bekerja dalam tim; 10. Tidak berstatus sebagai ASN (PNS/TNI/Polri/); 11. Berpengalaman dalam pengelolaan data kuantitatif; 12. Memiliki inisiatif untuk mempelajari isu-isu terkini, mengidentifikasi kebutuhan pengumpulan data, serta berkoordinasi dengan berbagai pihak terkait untuk mempercepat pencapaian output;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2869084);
