INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66599679', 66599679, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Penyusunan Rancangan Pengelolaan dan Implementasi Proyek SMART', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 485000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Kegiatan SMART mencakup tiga komponen utama yang saling mendukung dalam memperkuat peran ASN Perencana Pembangunan untuk mendorong peningkatan produktivitas nasional. Komponen 1 berfokus pada transformasi manajemen SDM melalui penyusunan Grand Design Pengembangan SDM ASN, penguatan tata kelola manajemen ASN, penguatan ekosistem ASN perencana, pengembangan kemitraan antara pemerintah, dunia pendidikan, dan industri, serta penyusunan desain kelembagaan dan peta jalan penguatan lembaga pengelolaan dan pengembangan SDM ASN perencana. Komponen 2 menitikberatkan pada peningkatan kapasitas ASN perencana berbasis kompetensi dan kinerja melalui transformasi sistem pengembangan kapasitas ASN perencana serta program pelatihan kritikal. Sementara itu, Komponen 3 mencakup dukungan terhadap tata kelola proyek melalui jasa konsultansi dalam manajemen proyek, keuangan, dan pengadaan, serta pelaksanaan pemantauan dan evaluasi proyek, guna memastikan efektivitas dan keberlanjutan hasil pelaksanaan SMART', '1. Memberikan supervisi atas pelaksanaan proyek; 2. Mengoordinasikan kegiatan pengadaan, pemantauan dan evaluasi (M&E), pelaporan, serta keterlibatan para pemangku kepentingan; 3. Memastikan keselarasan pelaksanaan proyek dengan BAPPENAS, Kementerian PANRB, dan JICA; 4. Kompetensi kunci: Perencanaan Proyek, financial management, pelaporan, pemantauan & evaluasi proyek, kepatuhan terhadap aturan JICA dan GOI', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2869732);
